pub(crate) fn sp_zone(page1: i32, views: &mut crate::port::Cells, srcview: i32, owords: &mut crate::port::Cells, etext: &mut crate::port::Cells, src: &crate::port::Bitmap, rules: &mut crate::port::Cells, r: i32, mut cand: &mut crate::port::Cells, mut mask: &mut crate::port::Cells) -> i32 {
    // Measure the zone of rules row r and, when its ink is a pen's, append a candidate to `cand` (see the head of this file). `mask` is the zone's ink map (one cell a pixel) and the
    // statistics after it. Answers 1 when a candidate was added.
    let rx0: i32 = rl_get(rules, r, rlf_x0()) - sp_side();
    let rx1: i32 = rl_get(rules, r, rlf_x1()) + sp_side();
    let ry: i32 = (rl_get(rules, r, rlf_y0()) + rl_get(rules, r, rlf_y1())) / 2;
    let th: i32 = rl_get(rules, r, rlf_y1()) - rl_get(rules, r, rlf_y0());
    let rpy: i32 = vw_cpt_to_px(views, srcview, 1, rx0, ry);
    let mut zx0: i32 = vw_cpt_to_px(views, srcview, 0, rx0, ry - sp_up());
    let mut zy0: i32 = vw_cpt_to_px(views, srcview, 1, rx0, ry - sp_up());
    let mut zx1: i32 = vw_cpt_to_px(views, srcview, 0, rx1, ry + sp_down());
    let mut zy1: i32 = vw_cpt_to_px(views, srcview, 1, rx1, ry + sp_down());
    let mut zw: i32 = 0;
    let mut zh: i32 = 0;
    let mut band: i32 = 2;
    let mut ink: i32 = 0;
    let mut k: i32 = 0;
    if zx0 < 0 {
        zx0 = 0;
    }
    if zy0 < 0 {
        zy0 = 0;
    }
    if zx1 > crate::port::bitmap_w(src) {
        zx1 = crate::port::bitmap_w(src);
    }
    if zy1 > crate::port::bitmap_h(src) {
        zy1 = crate::port::bitmap_h(src);
    }
    zw = zx1 - zx0;
    zh = zy1 - zy0;
    if (zw <= 8) || (zh <= 8) {
        return 0;
    }
    if (zw * zh) > sp_max_zone() {
        return 0;
    }
    band = 2 + (((th + 100) * zh) / (2 * (sp_up() + sp_down())));
    crate::port::cells_drop(mask, 0);
    while k < (zw * zh) {
        crate::port::cells_push(mask, 0);
        k += 1;
    }
    ink = sp_map(src, zx0, zy0, zw, zh, rpy, band, mask);
    if ink < sp_min_ink() {
        return 0;
    }
    sp_mask_words(page1, owords, etext, views, srcview, zx0, zy0, zw, zh, mask);
    ink = sp_stats(src, zx0, zy0, zw, zh, mask, zw * zh);
    if ink < sp_min_ink() {
        return 0;
    }
    return sp_judge(page1, views, srcview, owords, etext, src, rules, r, zx0, zy0, mask, zw * zh, zw, zh, cand);
}
pub fn sp_find(page1: i32, views: &mut crate::port::Cells, srcview: i32, rules: &mut crate::port::Cells, owords: &mut crate::port::Cells, etext: &mut crate::port::Cells, src: &crate::port::Bitmap, pw: i32, mut cand: &mut crate::port::Cells, mut mask: &mut crate::port::Cells) -> i32 {
    // The candidates of page `page1` (1-based) from the tracer's rules of the raster `srcview` (a `views` row; `src` its pixels): see the head of this file; written to `cand` (cleared
    // first). `mask` is scratch. Answers how many.
    let n: i32 = rl_count(rules);
    let mut r: i32 = 0;
    let mut looked: i32 = 0;
    crate::port::cells_drop(cand, 0);
    while r < n {
        if rl_get(rules, r, rlf_page()) == page1 {
            if (looked < sp_max()) && ((sp_is_rule(rules, r, pw) == 1) && (sp_framed(page1, rules, r, pw) == 0)) {
                looked += 1;
                sp_zone(page1, views, srcview, owords, etext, src, rules, r, cand, mask);
            }
        }
        r += 1;
    }
    return crate::port::cells_len(cand) / sp_w();
}
pub fn sp_record(page0: i32, cand: &mut crate::port::Cells, mut cg: &mut crate::port::Cells) -> i32 {
    // One correspondence group a candidate: no word, its box the ink's, its colour code (`sm-hue`) in `rot`, flagged `in-seal`, `seal-px` and `seal-sig` or `seal-init`. Answers the groups written.
    let n: i32 = crate::port::cells_len(cand) / sp_w();
    let mut j: i32 = 0;
    let mut c: i32 = 0;
    let mut g: i32 = 0;
    let mut fl: i32 = 0;
    while j < n {
        c = j * sp_w();
        g = cg_new(cg, page0 + 1, crate::port::cells_at(cand, c + 2), crate::port::cells_at(cand, c + 3), crate::port::cells_at(cand, c + 4), crate::port::cells_at(cand, c + 5), sm_hue(crate::port::cells_at(cand, c + 7)));
        fl = plg_in_seal() + plg_seal_px();
        if crate::port::cells_at(cand, c) == 3 {
            fl += plg_seal_sig();
        } else {
            fl += plg_seal_init();
        }
        cg_set(cg, g, cgf_flags(), fl);
        j += 1;
    }
    return n;
}
pub fn sp_drop_lines(mut scr: &mut crate::port::Cells, nsel: i32, olines: &mut crate::port::Cells, owords: &mut crate::port::Cells, cand: &mut crate::port::Cells) -> i32 {
    // A scanned page's chosen lines (the selection of `scr`) without the lines that the strokes of a candidate made: every word of the line has its centre in a candidate's box and the engine
    // was under 600 per mille sure of them on average (a typed name the strokes are drawn over is read with confidence and stays), or at least 60 per cent of them do and it was under 450.
    // Answers the lines left.
    let n: i32 = crate::port::cells_len(cand) / sp_w();
    let mut k: i32 = 0;
    let mut out: i32 = 0;
    let mut l: i32 = 0;
    let mut f: i32 = 0;
    let mut cnt: i32 = 0;
    let mut j: i32 = 0;
    let mut q: i32 = 0;
    let mut nin: i32 = 0;
    let mut csum: i32 = 0;
    let mut inone: i32 = 0;
    let mut wi: i32 = 0;
    let mut gone: i32 = 0;
    let mut cx: i32 = 0;
    let mut cy: i32 = 0;
    while k < nsel {
        l = crate::port::cells_at(scr, sc_sel_base() + k);
        f = ol_get(olines, l, lh_first());
        cnt = ol_get(olines, l, lh_count());
        nin = 0;
        csum = 0;
        gone = 0;
        if cnt > 0 {
            j = 0;
            while j < cnt {
                wi = f + j;
                cx = (ow_get(owords, wi, hd_x0()) + ow_get(owords, wi, hd_x1())) / 2;
                cy = (ow_get(owords, wi, hd_y0()) + ow_get(owords, wi, hd_y1())) / 2;
                inone = 0;
                q = 0;
                while q < n {
                    if (cx >= crate::port::cells_at(cand, (q * sp_w()) + 2)) && ((cx <= crate::port::cells_at(cand, (q * sp_w()) + 4)) && ((cy >= crate::port::cells_at(cand, (q * sp_w()) + 3)) && (cy <= crate::port::cells_at(cand, (q * sp_w()) + 5)))) {
                        inone = 1;
                    }
                    q += 1;
                }
                if inone == 1 {
                    nin += 1;
                }
                csum += ow_get(owords, wi, hd_conf());
                j += 1;
            }
            if (nin == cnt) && (csum < (cnt * 600)) {
                gone = 1;
            }
            if ((nin * 100) >= (cnt * 60)) && (csum < (cnt * 450)) {
                gone = 1;
            }
        }
        if gone == 0 {
            crate::port::cells_set(scr, sc_sel_base() + out, l);
            out += 1;
        }
        k += 1;
    }
    return out;
}
